using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace LoopFive {
 public class SceneView:Control {
  Engine engine;Rectangle[] pads=new Rectangle[5];
  public SceneView(Engine e){engine=e;Dock=DockStyle.Fill;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Cursor=Cursors.Hand;AccessibleName="Escena animada. Pulsa un anillo para grabar o reproducir su pista.";MouseDown+=delegate(object sender,MouseEventArgs a){for(int i=0;i<5;i++)if(pads[i].Contains(a.Location))engine.Action(i);};}
  protected override void OnPaint(PaintEventArgs e){Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;Rectangle area=ClientRectangle;if(Width<10||Height<10)return;using(Brush b=new LinearGradientBrush(area,Color.FromArgb(7,8,13),Color.FromArgb(48,21,25),90))g.FillRectangle(b,area);float time=Theme.Animate?(Environment.TickCount&int.MaxValue)/1000f:0;float strength=MathX.Clamp(engine.System.SceneIntensity,0,1);float energy=Math.Min(1,engine.OutputPeak+engine.InputPeak);int horizon=(int)(Height*.7f);
   // Distant crags, ember haze and a silhouetted performer are drawn locally.
   for(int layer=0;layer<3;layer++){PointF[] peaks=new PointF[14];peaks[0]=new PointF(0,Height);for(int i=1;i<13;i++)peaks[i]=new PointF((i-1)*Width/11f,horizon-35-layer*22+(float)Math.Sin(i*3.2+layer)*50);peaks[13]=new PointF(Width,Height);using(Brush b=new SolidBrush(Color.FromArgb(24+layer*8,21+layer*4,29+layer*5)))g.FillPolygon(b,peaks);}
   for(int i=0;i<26;i++){float x=(i+.5f)*Width/26f;Flame(g,x,Height+15,Width/20f,Height*(.15f+.13f*(float)(.5+.5*Math.Sin(i*2.4)))+energy*Height*.12f,time+i*.8f,Color.FromArgb((int)(135*strength),255,96,70));Flame(g,x,Height+8,Width/40f,Height*(.08f+.09f*(float)(.5+.5*Math.Sin(i*1.7)))+energy*Height*.07f,time+i,Color.FromArgb((int)(210*strength),255,188,99));}
   float cx=Width*.5f,cy=Height*.69f;using(Brush black=new SolidBrush(Color.FromArgb(9,9,14))){g.FillEllipse(black,cx-12,cy-23,24,27);PointF[] body={new PointF(cx-15,cy+6),new PointF(cx+13,cy+6),new PointF(cx+21,cy+67),new PointF(cx+9,cy+69),new PointF(cx+17,Height),new PointF(cx+4,Height),new PointF(cx-4,cy+75),new PointF(cx-16,Height),new PointF(cx-29,Height),new PointF(cx-16,cy+63)};g.FillPolygon(black,body);using(Pen p=new Pen(black,10)){g.DrawLine(p,cx-13,cy+15,cx-39,cy+61);g.DrawLine(p,cx+12,cy+16,cx+36,cy+51);}}
   for(int i=0;i<38;i++){float x=(i*137.1f+time*(8+i%6))%Width;float y=Height-((i*57.3f+time*(22+i%9))%(Height*.65f));using(Brush b=new SolidBrush(Color.FromArgb(90+i%100,255,140+i%100,105)))g.FillEllipse(b,x,y,2,3);}
   int cell=Width/5,diameter=Math.Min(132,Math.Min(cell-32,(int)(Height*.30f)));for(int i=0;i<5;i++){Track t=engine.Tracks[i];Color c=t.State==PlayState.Recording?Theme.NamedColor(engine.System.RecordColor):t.State==PlayState.Overdubbing?Theme.NamedColor(engine.System.DubColor):t.Playing?Theme.NamedColor(engine.System.PlayColor):Color.FromArgb(255,129,161);Rectangle r=new Rectangle(i*cell+(cell-diameter)/2,60,diameter,diameter);pads[i]=r;using(Brush b=new SolidBrush(Color.FromArgb(215,10,10,17)))g.FillEllipse(b,r);for(int glow=14;glow>=4;glow-=5)using(Pen p=new Pen(Color.FromArgb(16,c),glow))g.DrawEllipse(p,r);using(Pen p=new Pen(Color.FromArgb(70,c),5))g.DrawEllipse(p,r);float progress=t.Playing&&t.Clip!=null?(float)(t.Position/t.Clip.Length):t.State==PlayState.Recording?(float)((engine.Beat-t.RecordStartBeat)/engine.BarBeats%1):0;using(Pen p=new Pen(c,5)){p.StartCap=p.EndCap=LineCap.Round;g.DrawArc(p,r,-90,Math.Max(8,progress*359));}Rectangle inner=Rectangle.Inflate(r,-13,-13);using(Pen p=new Pen(Color.FromArgb(170,c),2))g.DrawEllipse(p,inner);TextRenderer.DrawText(g,t.State==PlayState.Recording?"●":t.Playing?"▶":"●",Theme.Ring,inner,c,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);TextRenderer.DrawText(g,"0"+(i+1)+"  /  "+Language.TrackName(t.Config,i),Theme.Small,new Rectangle(i*cell+4,25,cell-8,24),Color.FromArgb(224,221,233),TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);TextRenderer.DrawText(g,Language.T(t.State==PlayState.Recording?"GRABANDO":t.State==PlayState.Overdubbing?"OVERDUB":t.Playing?"PLAY":"LISTA"),Theme.Small,new Rectangle(i*cell,r.Bottom+15,cell,22),c,TextFormatFlags.HorizontalCenter);}
   TextRenderer.DrawText(g,"I N F E R N O   /   LIVE SESSION",Theme.Medium,new Rectangle(20,Height-37,Width-40,24),Color.FromArgb(255,213,193),TextFormatFlags.HorizontalCenter);
  }
  public static void Flame(Graphics g,float x,float bottom,float width,float height,float time,Color color){float bend=(float)Math.Sin(time*1.3)*width*.8f;using(GraphicsPath p=new GraphicsPath()){p.AddBezier(x-width,bottom,x-width*1.8f,bottom-height*.45f,x+width+bend,bottom-height*.55f,x+bend,bottom-height);p.AddBezier(x+bend,bottom-height,x+width*.2f,bottom-height*.45f,x+width*1.7f,bottom-height*.25f,x+width,bottom);p.CloseFigure();using(Brush b=new LinearGradientBrush(new PointF(x,bottom),new PointF(x,bottom-height),color,Color.FromArgb(0,color)))g.FillPath(b,p);}}
 }
}
